async def join_retirement(task: asyncio.Future):
    """Join owned cleanup through repeated cancellation, then propagate it."""
    interrupted = None
    while not task.done():
        try:
            await asyncio.shield(task)
        except asyncio.CancelledError as error:
            interrupted = error
    result = task.result()
    if interrupted is not None:
        raise interrupted
    return result

def _held_store_source(store_path, lock_file, platform, max_bus_bytes):
    """One durability guard after physical custody, with exact release on refusal."""
    try:
        if max_bus_bytes is not None:
            if type(max_bus_bytes) is not int or max_bus_bytes < 0:
                raise ValueError("bus read cap must be a nonnegative integer")
            if store_path.exists():
                bus_info = store_path.lstat()
                if not stat.S_ISREG(bus_info.st_mode) or bus_info.st_size > max_bus_bytes:
                    raise RelationViolationError("Bus exceeds bounded read budget.")
        from .wire_log import WireLog

        with WireLog(store_path).verify_before_read_unlocked() as source:
            yield StoreLock(lock_file.fileno(), source)
    finally:
        platform.release_store_lock(lock_file.fileno())

def record_turn_publication(
        self, *, lease: TurnLeaseFence, checkpoint: TranscriptCursor,
        routing: TurnRouting, published: tuple[MessageReference, ...],
    ) -> None:
        """Publish original native/wire relations before this exact turn retires."""
        self.routes.record_turn_publication(
            self.registry, self.bus.log, lease, checkpoint, routing, published
        )

async def committed_progress(self, event: events.CommittedProgress) -> None:
        if self.reply_targets:
            progress = event.text
            if progress and "".join(self.reply_parts) == progress:
                # Pi committed this assistant message before tool work.
                # Publish it once as visible, non-waking progress; the
                # final reply contains only subsequent assistant text.
                for target in self.reply_targets:
                    self.comms.messaging.send(self.thread_name, target, progress, notice=True)
                self.reply_parts.clear()

def publish_success(self) -> None:
        """Join each acquired original send before releasing the turn lease."""
        published: list[MessageReference] = []

        def record_publication() -> None:
            self.comms.transcripts.record_turn_publication(
                lease=self.turn_lease,
                checkpoint=self.checkpoint,
                routing=self.routing,
                published=tuple(published),
            )

        with ExitStack() as publications:
            publications.callback(record_publication)
            if self.reply_parts:
                for target in self.reply_targets:
                    message = self.comms.messaging.send_message(
                        self.thread_name, target, "".join(self.reply_parts)
                    )
                    published.append(message.reference)

def _read_certified(self, lock_file, platform, read):
        with _held_store_source(self.path, lock_file, platform, None) as lock:
            with self._certified_source(lock) as source:
                return read(source)
